                        line_spacing=block.line_height,
                        char_spacing=block.char_spacing,
                        min_font_size=8.0,
                        max_font_size=72.0
                    )

                    layout_blocks.append(layout_block)

        self.stats['total_blocks'] = len(layout_blocks)
